- [ ] 2. In `src/ratings.js`, add the import and the notification branch:
      ```js
      'use strict';
      const { STATUS } = require('./tickets');
      const { notifyAgent } = require('./notify');

      const LOW_SCORE_THRESHOLD = 2;

      function rateTicket(store, ticket, score, { now = new Date() } = {}) {
        if (!Number.isInteger(score) || score < 1 || score > 5) {
          throw new Error('a rating must be a whole number from 1 to 5');
        }
        if (ticket.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${ticket.status} ticket`);
        if (store.getRating(ticket.id)) throw new Error('this ticket already has a rating');
        const rating = { score, rated_at: now.toISOString() };
