        if (score <= LOW_SCORE_THRESHOLD && ticket.owner_id) {
          notifyAgent(store, ticket.owner_id, { type: 'low_csat_rating', ticketId: ticket.id, score });
        }
        return rating;
      }

      module.exports = { rateTicket, LOW_SCORE_THRESHOLD };
