      ```js
      'use strict';
      // Nightly. For each agent, counts ratings on their tickets from the past seven days and the average score.
      const WINDOW_DAYS = 7;
      const DAY = 24 * 60 * 60 * 1000;

      function csatSummary(store, { now = new Date() } = {}) {
        const cutoff = now.getTime() - WINDOW_DAYS * DAY;
        const byAgent = new Map();
        for (const r of store.listRatings()) {
          if (new Date(r.rated_at).getTime() < cutoff) continue;
          const ticket = store.getTicket(r.ticket_id);
          if (!ticket || !ticket.owner_id) continue;
          const scores = byAgent.get(ticket.owner_id) || [];
          scores.push(r.score);
          byAgent.set(ticket.owner_id, scores);
        }
        const summaries = [];
        for (const [agentId, scores] of byAgent) {
          const count = scores.length;
          const average = Math.round((scores.reduce((a, b) => a + b, 0) / count) * 100) / 100;
          const summary = { agent_id: agentId, count, average, period_end: now.toISOString() };
          store.setAgentSummary(agentId, summary);
          summaries.push(summary);
        }
        return summaries;
      }

      module.exports = { csatSummary, WINDOW_DAYS };
      ```
